// Class 11 Business Studies practice bank, part 1: Business, Trade and Commerce, Forms of Business Organisation, Private, Public and Global Enterprises, Business Services, Emerging Modes of Business.
StudyData.addPractice(11, "business", {
  "business-trade-and-commerce": {
    mcq: [
      { q: "The Hundi, used by Indian traders in the past, was:", options: ["A guild that framed rules of business", "An indigenous instrument for transferring money and giving credit", "A major inland trade centre", "A tax on exported spices"], answer: 1, explain: "A hundi was an indigenous credit instrument, similar to a bill of exchange. Guilds were called shrenis.", level: 1 },
      { q: "Which of the following is an economic activity?", options: ["A mother cooking for her family", "A volunteer cleaning a temple", "A man donating blood to a stranger", "A tailor stitching clothes for customers for a price"], answer: 3, explain: "Economic activities are done to earn a living. The tailor works for a price; the other activities are done out of love, sympathy or religious feeling.", level: 1 },
      { q: "The reward for a person practising a profession such as law is called:", options: ["Profit", "Salary", "Wages", "Professional fee"], answer: 3, explain: "Business earns profit, employment earns salary or wages, and a profession earns professional fee.", level: 1 },
      { q: "Insurance as an auxiliary to trade removes the hindrance of:", options: ["Place", "Time", "Risk", "Finance"], answer: 2, explain: "Insurance covers the risk of loss or damage to goods. Transport removes place, warehousing removes time, banking removes finance.", level: 1 },
      { q: "Which of the following is an extractive industry?", options: ["Cement manufacturing", "Banking", "Poultry breeding", "Fishing"], answer: 3, explain: "Extractive industries take out products from nature, e.g. farming, mining, fishing and lumbering. Poultry breeding is a genetic industry.", level: 1 },

      { q: "Case: Kaveri Agro Nursery in Coimbatore raises mango and coconut saplings from selected seeds and sells them to farmers.\nThis firm belongs to which type of industry?", options: ["Extractive industry", "Genetic industry", "Processing industry", "Tertiary industry"], answer: 1, explain: "Breeding of plants and animals (nurseries, poultry, cattle-breeding farms) is a genetic industry, a part of primary industries.", level: 2 },
      { q: "Case: Dr Meera Joshi runs a clinic and charges consultation fees. Her brother Vikram works in a bank and gets a monthly salary. Their cousin Rohan owns a grocery shop and keeps what is left after expenses.\nWhich statement is correct?", options: ["Meera earns profit, Vikram earns fee, Rohan earns salary", "Meera earns fee, Vikram earns salary, Rohan earns profit", "All three earn profit", "Meera earns salary, Vikram earns wages, Rohan earns fee"], answer: 1, explain: "Profession (doctor) gives fee, employment (bank clerk) gives salary, and business (shop) gives profit.", level: 2 },
      {
        q: "Assertion (A): Profit cannot be the only objective of a business.\nReason (R): A business needs objectives in several key areas such as innovation, productivity and social responsibility.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 0, explain: "Profit is needed, but a business must also set objectives in other key areas to survive and grow. R explains why profit alone is not enough.", level: 2, keepOrder: true
      },
      { q: "A paper mill turns bamboo pulp into paper through several successive stages. This is an example of which manufacturing industry?", options: ["Analytical", "Synthetical", "Assembling", "Processing"], answer: 3, explain: "Where the product passes through successive stages of production (sugar, paper), the industry is a processing industry.", level: 2 },
      { q: "Which of the following is NOT a characteristic of business?", options: ["Dealings on a regular basis", "Profit earning as the aim", "Fixed and assured return", "Element of risk"], answer: 2, explain: "Return in business is uncertain; profit may be high, low or even a loss. Regular dealings, profit motive and risk are features of business.", level: 2 },

      {
        q: "Assertion (A): Warehousing removes the hindrance of place.\nReason (R): Warehousing stores goods until they are needed, thereby creating time utility.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 3, explain: "Warehousing removes the hindrance of time, not place; transport removes the hindrance of place. R is true.", level: 3, keepOrder: true
      },
      { q: "Case: Sunrise Exports of Kochi buys cashew nuts from Vietnam and, without processing them, sells them to a buyer in Italy.\nThis activity of Sunrise Exports is known as:", options: ["Export trade", "Import trade", "Wholesale trade", "Entrepôt trade"], answer: 3, explain: "Importing goods from one country in order to re-export them to another is entrepôt trade.", level: 3 },
      { q: "Which of the following lists contains only tertiary (service) activities?", options: ["Mining, banking, transport", "Fishing, transport, advertising", "Banking, advertising, warehousing", "Construction, insurance, communication"], answer: 2, explain: "Banking, advertising and warehousing support primary and secondary industries and are services. The other lists include mining, fishing or construction.", level: 3 },
      { q: "A strike by workers in a factory and a sudden fall in the demand for its product are examples of which causes of business risk respectively?", options: ["Natural; economic", "Economic; human", "Human; economic", "Human; natural"], answer: 2, explain: "Strikes and dishonesty are human causes. Changes in demand, prices and competition are economic causes.", level: 3 }
    ],
    written: [
      { q: "Define business.", a: "Business is an economic activity involving the regular production or purchase and sale of goods and services with the object of earning profit.", marks: 1 },
      { q: "What is a hundi?", a: "A hundi was an indigenous instrument of exchange, similar to a bill of exchange, used by Indian traders to transfer money and give credit.", marks: 1 },
      { q: "Distinguish between a profession and employment on the basis of (a) reward and (b) mode of establishment.", a: "(a) Reward: a profession earns professional fee; employment earns salary or wages.\n(b) Mode of establishment: a profession is entered by membership of a professional body and a certificate of practice; employment is entered by an appointment letter and a service agreement.", marks: 2 },
      { q: "Name any two auxiliaries to trade and state the hindrance each removes.", a: "(i) Transport removes the hindrance of place.\n(ii) Warehousing removes the hindrance of time. (Insurance removes risk, banking removes finance, advertising removes lack of information.)", marks: 2 },
      { q: "Explain any three characteristics of business.", a: "(i) Economic activity: it is done to earn a living.\n(ii) Regular dealings: production or purchase and sale takes place on a regular basis; a single sale is not business.\n(iii) Profit earning and risk: profit is the aim, but returns are uncertain and there is always an element of risk.", marks: 3 },
      { q: "Why should profit not be the only objective of a business? Give three points.", a: "(i) Profit is needed as a source of income, as a source of finance for expansion, as an indicator of efficiency and to build reputation.\n(ii) But a business also needs objectives in other areas such as market standing, innovation and productivity, otherwise it cannot survive in the long run.\n(iii) A business must also meet its social responsibility and care for workers and managers; a single-minded chase for profit can harm these.", marks: 3 },
      { q: "Explain any three types of manufacturing industry with one example each.", a: "(i) Analytical: separates a product into several useful products, e.g. oil refining.\n(ii) Synthetical: combines several raw materials into a new product, e.g. cement.\n(iii) Processing: the product passes through successive stages, e.g. sugar or paper. (Assembling puts parts together, e.g. cars, computers.)", marks: 3 },
      { q: "Explain the classification of business activities with suitable examples.", a: "Business activities are divided into industry and commerce.\n1. Industry (production) has three types: primary, secondary and tertiary.\n2. Primary: extractive (farming, mining, fishing, lumbering) and genetic (nurseries, poultry, cattle-breeding farms).\n3. Secondary: manufacturing (analytical, synthetical, processing, assembling) and construction.\n4. Tertiary: services that support other industries, e.g. transport, banking, insurance, warehousing, communication, advertising.\n5. Commerce = trade + auxiliaries to trade. Trade may be internal (wholesale, retail) or external (import, export, entrepôt); auxiliaries remove hindrances of place, time, risk, finance and information.", marks: 5 },
      { q: "What is business risk? Explain its nature and any three causes.", a: "Business risk is the possibility of inadequate profits or even losses due to uncertainties or unexpected events.\nNature: (i) it arises from uncertainties; (ii) it is an essential part of every business; (iii) its degree depends on the nature and size of the business; (iv) profit is the reward for risk taking.\nCauses: (i) Natural causes such as flood and earthquake; (ii) human causes such as dishonesty, strikes and mismanagement; (iii) economic causes such as changes in demand, competition, prices and technology.", marks: 5 },
      { q: "Case study: Bhavna Spices of Guntur buys chillies, turmeric and coriander from farmers, blends them into masala mixes and packs them. The mixes are kept in a rented warehouse and insured against fire before being sold to retailers. The owner's brother Karan runs a cattle-breeding farm.\n(i) Under which type of primary industry does Karan's work fall?\n(ii) Name the hindrances removed by the warehouse and by the insurance.\n(iii) Which type of manufacturing is blending several ingredients into a masala mix?", a: "(i) Genetic industry (breeding of animals).\n(ii) The warehouse removes the hindrance of time; insurance removes the hindrance of risk.\n(iii) Synthetical industry, because several materials are combined into one product.", marks: 4, type: "case" }
    ]
  }
,
  "forms-of-business-organisation": {
    mcq: [
      { q: "The liability of a sole proprietor for the debts of his business is:", options: ["Limited to his capital in the business", "Limited to the extent of his share in profits", "Unlimited", "Nil, as the business is a separate legal entity"], answer: 2, explain: "A sole proprietorship has no separate legal entity, so the owner's personal assets can be used to pay business debts: his liability is unlimited.", level: 1 },
      { q: "The head of a Joint Hindu Family business who controls it is called the:", options: ["Karta", "Coparcener", "Managing partner", "Secretary"], answer: 0, explain: "The eldest member, who manages and controls the joint Hindu family business, is the Karta.", level: 1 },
      { q: "The maximum number of members in a partnership firm is:", options: ["10", "20", "100", "50"], answer: 3, explain: "A partnership must have at least 2 and, as per the limit prescribed under the Companies Act, 2013, at most 50 members.", level: 1 },
      { q: "A cooperative society needs at least how many adult members for registration?", options: ["7", "10", "2", "20"], answer: 1, explain: "A cooperative society can be formed with a minimum of 10 adult members.", level: 1 },
      { q: "Which document is conclusive proof that a company legally exists?", options: ["Memorandum of Association", "Articles of Association", "Partnership deed", "Certificate of Incorporation"], answer: 3, explain: "The Registrar issues the Certificate of Incorporation, which is conclusive proof of the company's legal existence.", level: 1 },

      { q: "Case: Arjun, Bela and Chirag start a bakery in Ludhiana on a verbal understanding to share profits equally. Any one of them can bind the others by dealing with a supplier on behalf of the bakery.\nThis feature of partnership is called:", options: ["Perpetual succession", "Mutual agency", "Limited liability", "Separate legal entity"], answer: 1, explain: "Each partner is both an agent and a principal for the others. This is mutual agency.", level: 2 },
      { q: "Case: Farmers of a village near Anand have formed an association to pool and sell their milk. Every member has one vote irrespective of the money invested, and the aim is the welfare of members.\nThis form of organisation is a:", options: ["Joint stock company", "Partnership", "Cooperative society", "Joint Hindu Family business"], answer: 2, explain: "Voluntary membership, welfare motive and one member, one vote are features of a cooperative society.", level: 2 },
      {
        q: "Assertion (A): A sleeping partner is not liable for the debts of the firm.\nReason (R): A sleeping partner does not take part in the management of the firm.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 3, explain: "A sleeping partner contributes capital and shares profits but takes no part in management; his liability is still unlimited. So A is false and R is true.", level: 2, keepOrder: true
      },
      { q: "Which of the following is correct for a private company?", options: ["Minimum 7 members and free transfer of shares", "Minimum 2 members and it may invite the public to buy shares", "Maximum 50 members and no directors", "Minimum 2 members, minimum 2 directors and restricted transfer of shares"], answer: 3, explain: "A private company has 2 to 200 members, a minimum of 2 directors, restricts share transfer and cannot invite the public to subscribe.", level: 2 },
      { q: "A person who only lends his name to a partnership firm, without investing capital or taking part in management, is called a:", options: ["Sleeping partner", "Secret partner", "Nominal partner", "Active partner"], answer: 2, explain: "A nominal partner only lends his name but is still liable to outsiders.", level: 2 },

      {
        q: "Assertion (A): A company is called an artificial person.\nReason (R): It is created by law and has a legal status separate from its members, so it can own property and sue or be sued.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 0, explain: "A company is formed by law, not born, and has its own legal identity. R correctly explains A.", level: 3, keepOrder: true
      },
      { q: "A Joint Hindu Family business owes ₹12 lakh, but the family property is worth only ₹7 lakh. Who can be made to pay the remaining ₹5 lakh from personal assets?", options: ["All coparceners equally", "Only the Karta", "Only the youngest coparcener", "Nobody, as liability is limited for all"], answer: 1, explain: "Only the Karta has unlimited liability. The liability of other coparceners is limited to their share in the family property.", level: 3 },
      { q: "Case: Mr Gill is not a partner in Gill & Sons, but he tells a supplier, 'I am one of the partners', and the supplier sells goods to the firm on credit relying on this.\nMr Gill is liable to the supplier as a:", options: ["Sleeping partner", "Partner by estoppel", "Secret partner", "Minor partner"], answer: 1, explain: "A person who by his own words or conduct gives the impression that he is a partner is a partner by estoppel, and is liable to third parties who relied on it.", level: 3 },
      { q: "A business needs very large capital, limited liability for owners and perpetual existence. Which form is most suitable?", options: ["Sole proprietorship", "Partnership", "Joint Hindu Family business", "Public company"], answer: 3, explain: "A public company can raise large capital from the public, gives limited liability to shareholders and continues despite changes in membership.", level: 3 }
    ],
    written: [
      { q: "Name the Act which governs partnership in India.", a: "The Indian Partnership Act, 1932.", marks: 1 },
      { q: "What is a partnership deed?", a: "A written agreement among the partners that covers matters such as name and nature of the firm, capital, profit-sharing ratio, interest on capital and drawings, salaries, duties of partners and rules for admission and retirement.", marks: 1 },
      { q: "Distinguish between a sleeping partner and a secret partner.", a: "(i) A sleeping partner contributes capital and shares profits but takes no part in management; his association may be known to the public.\n(ii) A secret partner takes part in the business, but his association with the firm is not known to the public. Both have unlimited liability.", marks: 2 },
      { q: "Who is the Karta of a Joint Hindu Family business? State his liability.", a: "The Karta is the eldest member of the family who manages and controls the business. His liability is unlimited, while that of the other coparceners is limited to their share in the family property.", marks: 2 },
      { q: "Explain any three limitations of sole proprietorship.", a: "(i) Limited resources: the owner's own savings and borrowings restrict the size of the business.\n(ii) Limited life: the death, insolvency or illness of the owner can end the business.\n(iii) Unlimited liability: the owner's personal property can be used to pay business debts. (Limited managerial ability is another.)", marks: 3 },
      { q: "State the purpose of (a) the Memorandum of Association, (b) the Articles of Association and (c) the Certificate of Incorporation.", a: "(a) The Memorandum of Association is the company's charter; it defines the objects and scope of the company.\n(b) The Articles of Association contain the rules for the internal management of the company.\n(c) The Certificate of Incorporation is conclusive proof that the company has been legally formed.", marks: 3 },
      { q: "Distinguish between a private company and a public company on any three bases.", a: "(i) Membership: private 2 to 200 members; public minimum 7 and no maximum.\n(ii) Transfer of shares: restricted in a private company; freely transferable in a public company.\n(iii) Public invitation: a private company cannot invite the public to subscribe to its securities; a public company can. (Minimum directors: 2 and 3 respectively.)", marks: 3 },
      { q: "Explain any five features of a partnership.", a: "1. Formed by agreement: oral or written; the written agreement is called a partnership deed.\n2. Members: minimum 2 and maximum 50.\n3. Unlimited, joint and several liability of partners.\n4. Shared risk, decision making and control among partners.\n5. Mutual agency: each partner is both an agent and a principal.\n6. Lack of continuity: death, retirement or insolvency of a partner may dissolve the firm.", marks: 5 },
      { q: "Explain any five factors which should be considered while choosing a form of business organisation.", a: "1. Cost and ease of setting up the business.\n2. Liability: whether owners are ready to bear unlimited liability.\n3. Continuity of the business despite changes in ownership.\n4. Management ability: the skills available to run the business.\n5. Capital requirements: how much money has to be raised.\n6. Degree of control the owners want to keep.\n7. Nature of the business. (Any five.)", marks: 5 },
      { q: "Case study: The Jaggi family of Amritsar has run a furniture business for four generations. Members of the family get a right in the business by birth, and all decisions are taken by the eldest member. When he died, his eldest son took over. In the same village, twelve women formed a society to give each other cheap loans and keep out moneylenders; each member has one vote.\n(i) Identify the form of the Jaggi business.\n(ii) What happens to the business on the death of its head, and who takes over?\n(iii) Name the type of the women's society and state the voting rule.", a: "(i) A Joint Hindu Family business.\n(ii) The business continues without a break (continuity); the next eldest member becomes the Karta.\n(iii) A credit cooperative society; each member has one vote, irrespective of the capital contributed.", marks: 4, type: "case" }
    ]
  }
,
  "private-public-and-global-enterprises": {
    mcq: [
      { q: "The Life Insurance Corporation of India is an example of a:", options: ["Departmental undertaking", "Government company", "Statutory corporation", "Joint venture"], answer: 2, explain: "LIC was created by a Special Act of Parliament, so it is a statutory corporation.", level: 1 },
      { q: "Indian Railways is run as a:", options: ["Government company", "Departmental undertaking", "Statutory corporation", "Private company"], answer: 1, explain: "Indian Railways and the Department of Posts are set up as departments of a ministry.", level: 1 },
      { q: "A government company is one in which the government holds at least what percentage of the paid-up share capital?", options: ["26%", "49%", "74%", "51%"], answer: 3, explain: "Under the Companies Act, 2013, a government company has not less than 51% of its paid-up capital held by the Central or State Governments or both.", level: 1 },
      { q: "Joint ventures can broadly be of which two types?", options: ["Contractual and equity-based", "Private and public", "Domestic and export", "Departmental and statutory"], answer: 0, explain: "A contractual joint venture creates no new firm, while an equity-based one creates a new jointly owned firm.", level: 1 },
      { q: "Selling a part of the government's shareholding in public sector undertakings to private investors is called:", options: ["Nationalisation", "Privatisation of the whole sector", "Import substitution", "Disinvestment"], answer: 3, explain: "Disinvestment means selling part of the government's equity in PSUs.", level: 1 },

      { q: "Case: Bharat Sagar Ports Ltd is registered under the Companies Act, 2013, has a board of directors and its shares are 74% held by the Central Government.\nThis enterprise is a:", options: ["Departmental undertaking", "Statutory corporation", "Government company", "Cooperative society"], answer: 2, explain: "A company registered under the Companies Act with at least 51% government shareholding is a government company.", level: 2 },
      { q: "Case: Jan Bijli Nigam supplies electricity to a state. It was created by a special Act of the State Legislature, raises its own funds and its employees are not civil servants.\nThis enterprise is a:", options: ["Government company", "Departmental undertaking", "Joint venture", "Statutory corporation"], answer: 3, explain: "An enterprise created by a Special Act of a State Legislature with financial independence and non-civil-servant staff is a statutory corporation.", level: 2 },
      {
        q: "Assertion (A): A departmental undertaking is most suitable where national security is involved.\nReason (R): It is financed from the Government Treasury and is under effective control of Parliament.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 0, explain: "Direct ministerial control, government funding and parliamentary supervision make secrecy and accountability easier, so it suits security-related work.", level: 2, keepOrder: true
      },
      { q: "Which of the following is a feature of a multinational (global) enterprise?", options: ["Control is decentralised to each country", "Operations in only one country", "Centralised control by the head office in the home country", "A small capital base"], answer: 2, explain: "Global enterprises operate in many countries but are controlled centrally by the head office in the home country.", level: 2 },
      { q: "Which of the following is NOT a feature of a statutory corporation?", options: ["Created by a Special Act", "Separate legal entity", "Can sue and be sued", "Employees are government servants bound by civil service rules"], answer: 3, explain: "Employees of a statutory corporation are not civil servants. Their service conditions are set by the corporation.", level: 2 },

      {
        q: "Assertion (A): A government company is not directly answerable to Parliament.\nReason (R): It is a separate legal entity, registered under the Companies Act and managed by a board of directors.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 1, explain: "Both statements are correct, but being a company does not by itself explain the lack of direct accountability to Parliament, so R is not the correct explanation.", level: 3, keepOrder: true
      },
      { q: "Case: Indo-Arc Motors and Tokaido Gears set up a new company, Indo-Tokaido Gears Ltd, which they own equally, to make gearboxes.\nThis arrangement is a:", options: ["Contractual joint venture", "Equity-based joint venture", "Statutory corporation", "Public Private Partnership"], answer: 1, explain: "Creation of a new jointly owned firm makes it an equity-based joint venture. In a contractual one, no new firm is formed.", level: 3 },
      { q: "A company is registered under the Companies Act. 49% of its paid-up capital is held by the Central Government and 51% by a private firm. It is:", options: ["A government company, as the government is a shareholder", "Not a government company, as the government holds less than 51%", "A statutory corporation, as the government holds shares", "A departmental undertaking"], answer: 1, explain: "To be a government company, the government must hold at least 51% of paid-up capital. Here it holds only 49%.", level: 3 },
      { q: "Case: A State Government and a private firm agree to build and run a toll highway, with the firm investing money and both sharing the risk and the rewards.\nThis arrangement is called:", options: ["Disinvestment", "Statutory corporation", "Public Private Partnership", "Departmental undertaking"], answer: 2, explain: "When government and a private firm share resources, risks and rewards to provide public infrastructure, it is a PPP.", level: 3 }
    ],
    written: [
      { q: "What is a departmental undertaking? Give one example.", a: "It is an enterprise set up as a department of a government ministry and treated as its extension, e.g. Indian Railways or the Department of Posts.", marks: 1 },
      { q: "What is a government company?", a: "A company registered under the Companies Act, 2013 in which not less than 51% of the paid-up share capital is held by the Central Government, State Government(s) or both.", marks: 1 },
      { q: "State any two limitations of statutory corporations.", a: "(i) In practice they rarely enjoy full autonomy, and political interference persists.\n(ii) Any change needs an amendment of the Act, which makes them rigid.", marks: 2 },
      { q: "State any two limitations of a government company.", a: "(i) The government is the main shareholder, so many provisions of the Companies Act have little meaning for it.\n(ii) It is not directly answerable to Parliament.", marks: 2 },
      { q: "Explain any three features of a statutory corporation.", a: "(i) It is created by a Special Act of Parliament or a State Legislature, which defines its powers and functions.\n(ii) It is a separate legal entity: it can sue and be sued, enter contracts and own property.\n(iii) It is usually independently financed and is not subject to government accounting and audit rules; its employees are not civil servants.", marks: 3 },
      { q: "Explain any three reasons for which the public sector was set up in India.", a: "(i) To build infrastructure for economic growth.\n(ii) To promote regional balance by setting up units in backward areas.\n(iii) To prevent concentration of economic power in a few private hands. (Other reasons: economies of scale, import substitution.)", marks: 3 },
      { q: "Explain any three benefits of joint ventures.", a: "(i) More resources and capacity, since partners pool their strengths.\n(ii) Access to new markets and distribution networks.\n(iii) Access to technology and innovation, lower cost of production and the benefit of an established brand name.", marks: 3 },
      { q: "Explain the changing role of the public sector after the 1991 policy.", a: "1. The number of industries reserved exclusively for the public sector was reduced.\n2. Disinvestment began: part of the government's shareholding in PSUs was sold to private investors.\n3. Sick public sector units were referred to the Board for Industrial and Financial Reconstruction (BIFR).\n4. The Memorandum of Understanding (MoU) system gave PSU managements more autonomy but made them accountable for targets.\n5. Private participation was encouraged in providing public infrastructure and services, for example through Public Private Partnerships (PPP).", marks: 5 },
      { q: "Differentiate between a departmental undertaking, a statutory corporation and a government company on the basis of (a) formation, (b) legal status, (c) finance, (d) employees and (e) accountability or audit.", a: "(a) Formation: department of a ministry | Special Act of Parliament or State Legislature | registered under the Companies Act, 2013.\n(b) Legal status: an extension of the ministry, not a separate entity | separate legal entity | separate legal entity.\n(c) Finance: annual appropriation from the Treasury | usually own borrowing and sales revenue | share capital held by government (at least 51%) and private shareholders, plus the capital market.\n(d) Employees: government servants | not civil servants | company employees, not civil servants.\n(e) Accountability/audit: answerable to the ministry, government accounting and audit | free from government accounting and audit rules | auditor appointed on the advice of the CAG.", marks: 5 },
      { q: "Case study: Setu Infra Ltd, a private firm, signs an agreement with a State Government to build and run a toll highway, sharing risk and revenue. Jan Bijli Nigam supplies power and was formed by an Act of the State Legislature. Rail Setu Ltd, registered under the Companies Act, has 60% of its shares with the Central Government.\n(i) What is the arrangement between Setu Infra and the State Government called?\n(ii) Identify the type of public enterprise Jan Bijli Nigam is.\n(iii) Identify Rail Setu Ltd's form and state the minimum government holding needed for it.", a: "(i) A Public Private Partnership (PPP).\n(ii) A statutory corporation, since it was created by a Special Act of a State Legislature.\n(iii) A government company; the government must hold at least 51% of its paid-up share capital (here 60%).", marks: 4, type: "case" }
    ]
  }
,
  "business-services": {
    mcq: [
      { q: "The feature of services that they cannot be stored for future use is called:", options: ["Intangibility", "Inconsistency", "Involvement", "Inventory (less or none)"], answer: 3, explain: "Among the 5 I's, 'inventory' means services cannot be stored. An unused seat or hour of service is lost.", level: 1 },
      { q: "Which type of bank account is meant mainly for businesses and has no limit on the number of transactions?", options: ["Fixed deposit", "Current account", "Savings account", "Recurring deposit"], answer: 1, explain: "A current account suits businesses: there is no limit on the number of transactions and usually no interest is paid.", level: 1 },
      { q: "An instrument issued by a bank on its own branch elsewhere, payable on demand and not dishonoured for want of funds, is a:", options: ["Cheque", "Hundi", "Bank draft", "Postal order"], answer: 2, explain: "A bank draft is issued by a bank on its own branch at another place. It cannot be dishonoured for want of funds.", level: 1 },
      { q: "In RTGS, the minimum amount that can be transferred is:", options: ["₹2 lakh", "₹1 lakh", "₹10,000", "There is no minimum"], answer: 0, explain: "RTGS is for large-value transfers of a minimum of ₹2 lakh. NEFT has no minimum.", level: 1 },
      { q: "The amount paid by the insured to the insurer for the insurance cover is called the:", options: ["Premium", "Indemnity", "Subrogation", "Claim"], answer: 0, explain: "The insured pays a premium; in return the insurer agrees to compensate for the loss from specified risks.", level: 1 },

      { q: "Case: A yoga studio in Rishikesh has 20 seats in its 6 a.m. class, but only 12 are filled. The unfilled seats cannot be kept and sold in tomorrow's class.\nWhich feature of services does this show?", options: ["Intangibility", "Inventory (cannot be stored)", "Inconsistency", "Involvement"], answer: 1, explain: "Services cannot be stored. An empty seat today is lost income and cannot be carried to another day.", level: 2 },
      { q: "Case: Hari runs a printing press. His bank allows him to borrow up to ₹6 lakh against the security of his stock of paper and ink, and he pays interest only on the amount he actually uses.\nThis facility is:", options: ["A bank overdraft", "A recurring deposit", "Cash credit", "A bank draft"], answer: 2, explain: "A loan up to a limit against the security of current assets such as stock, with interest only on the amount used, is cash credit.", level: 2 },
      {
        q: "Assertion (A): Indemnity applies to all kinds of insurance.\nReason (R): Insurance compensates the insured only for the actual loss, not to make a profit.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 3, explain: "Indemnity applies to fire and marine insurance but not to life insurance, where a fixed sum is paid. So A is false; R states the principle correctly.", level: 2, keepOrder: true
      },
      { q: "A man did not disclose to the insurer, while taking a life policy, that he suffers from a serious heart disease. Which principle of insurance has he violated?", options: ["Insurable interest", "Utmost good faith", "Contribution", "Subrogation"], answer: 1, explain: "Both parties must disclose all material facts. Hiding a serious illness violates utmost good faith.", level: 2 },
      { q: "A fixed amount is deposited every month for a fixed period and repaid with interest on maturity. This is a:", options: ["Savings account", "Current account", "Fixed deposit", "Recurring deposit"], answer: 3, explain: "A recurring deposit involves regular monthly deposits of a fixed amount for a fixed period.", level: 2 },

      {
        q: "Assertion (A): RTGS is meant for large-value transfers.\nReason (R): RTGS has a minimum transfer limit of ₹2 lakh and settles each transaction individually in real time.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 0, explain: "RTGS settles each transfer one by one in real time and has a minimum of ₹2 lakh, so it is used for large amounts.", level: 3, keepOrder: true
      },
      { q: "Rohit bought a godown and took a fire insurance policy on it. He sold the godown, and two months later it was destroyed by fire. Can he claim from the insurer?", options: ["Yes, because he held the policy when the loss occurred", "Yes, because the policy was valid at the time of contract", "No, because he had no insurable interest at the time of loss", "No, because fire insurance is not a contract of indemnity"], answer: 2, explain: "In fire insurance, insurable interest must exist both at the time of the contract and at the time of loss. Rohit had sold the godown, so he had none at the time of loss.", level: 3 },
      { q: "A warehouse is insured against fire only. Its stock is destroyed in a flood. The insurer will:", options: ["Pay the full amount, as the stock is insured", "Pay half the amount", "Share the loss with the warehouse owner", "Not pay, because the proximate cause (flood) is not an insured risk"], answer: 3, explain: "Under the principle of proximate cause, the loss is paid only if the nearest cause is an insured risk.", level: 3 },
      { q: "Stock worth ₹8 lakh is insured for ₹10 lakh against fire. A fire destroys goods worth ₹3 lakh. The insurer will pay:", options: ["₹10 lakh", "₹7 lakh", "₹3 lakh", "₹5 lakh"], answer: 2, explain: "By the principle of indemnity, compensation is limited to the actual loss of ₹3 lakh, even though the sum insured is higher.", level: 3 }
    ],
    written: [
      { q: "What is a bank overdraft?", a: "A facility under which a current account holder is allowed to withdraw more than the balance in the account, up to an agreed limit; interest is charged on the amount overdrawn.", marks: 1 },
      { q: "What is subrogation in insurance?", a: "After the insurer has paid the claim, it takes over the insured's rights against third parties for the loss, along with any damaged property.", marks: 1 },
      { q: "Distinguish between RTGS and NEFT on any two bases.", a: "(i) Settlement: RTGS settles each transfer individually in real time; NEFT settles transfers in batches.\n(ii) Amount: RTGS has a minimum of ₹2 lakh; NEFT has no minimum limit.", marks: 2 },
      { q: "State any two differences between a savings account and a current account.", a: "(i) A savings account is meant to encourage savings by households and earns interest; a current account is meant for businesses and usually pays no interest.\n(ii) A current account has no limit on the number of transactions, and an overdraft facility may be given; a savings account does not offer this.", marks: 2 },
      { q: "Explain the three types of services with one example of each.", a: "(i) Business services support business activity, e.g. banking, insurance, transport, warehousing, communication.\n(ii) Social services are voluntary and aim at social welfare, e.g. health and education services run by NGOs.\n(iii) Personal services are used by individuals, and vary with the customer, e.g. tourism, recreation, restaurants.", marks: 3 },
      { q: "Distinguish between life insurance and fire insurance on the basis of (a) insurable interest, (b) indemnity and (c) what is covered.", a: "(a) Insurable interest: life insurance needs it at the time of the contract; fire insurance needs it at the time of the contract and at the time of loss.\n(b) Indemnity: it does not apply to life insurance; it applies to fire insurance.\n(c) Cover: life insurance pays a sum on death or maturity of the policy; fire insurance compensates loss from accidental fire.", marks: 3 },
      { q: "Explain any three features of services (the 5 I's).", a: "(i) Intangibility: services cannot be touched.\n(ii) Inconsistency: services differ every time according to customer demands.\n(iii) Inseparability: production and consumption of a service take place together. (Inventory: services cannot be stored; Involvement: the customer takes part in delivering the service.)", marks: 3 },
      { q: "Explain the different types of bank accounts.", a: "1. Savings account: encourages saving, earns interest, suited to households.\n2. Current account: for businesses; no limit on the number of transactions; usually no interest; overdraft may be allowed.\n3. Fixed deposit: money kept for a fixed period at a higher rate of interest; early withdrawal is allowed with some loss of interest.\n4. Recurring deposit: a fixed amount is deposited every month for a fixed period and repaid with interest on maturity.\n5. Multiple option deposit account: a savings account in which money above a set limit is automatically moved into fixed deposits, giving liquidity and higher interest.", marks: 5 },
      { q: "Explain any five principles of insurance.", a: "1. Utmost good faith: both parties must disclose all material facts.\n2. Insurable interest: the insured must stand to suffer a financial loss if the subject matter is damaged.\n3. Indemnity: the insured gets only the actual loss, not a profit (not applicable to life insurance).\n4. Proximate cause: the loss is paid only if the nearest cause is an insured risk.\n5. Subrogation: after paying, the insurer takes over the insured's rights against third parties.\n6. Contribution: if the same property is insured with several insurers, they share the loss in proportion.\n7. Mitigation of loss: the insured must take reasonable steps to reduce the loss. (Any five.)", marks: 5 },
      { q: "Case study: Gurdeep Auto Parts of Ludhiana needs to pay a supplier ₹5 lakh at once and wants each transfer settled individually in real time. His bank also allows him to withdraw more than his balance up to an agreed limit, charging interest only on the amount overdrawn. He has insured his godown against fire so that, if a fire occurs, he receives no more than his actual loss.\n(i) Which mode of fund transfer should he use for ₹5 lakh, and why?\n(ii) Name the bank facility and the type of account in which it is given.\n(iii) Which principle of insurance limits the compensation to his actual loss?", a: "(i) RTGS, because it settles each transfer individually in real time and is meant for amounts of at least ₹2 lakh.\n(ii) Bank overdraft, given to a current account holder.\n(iii) The principle of indemnity.", marks: 4, type: "case" }
    ]
  }
,
  "emerging-modes-of-business": {
    mcq: [
      { q: "Transactions between two business firms conducted through computer networks are called:", options: ["B2C", "C2C", "Intra-B", "B2B"], answer: 3, explain: "B2B means business-to-business, e.g. a car maker ordering components from suppliers online.", level: 1 },
      { q: "Which of the two terms is wider in meaning?", options: ["E-commerce", "E-business", "Both are exactly equal", "It cannot be compared"], answer: 1, explain: "E-business covers industry, trade and commerce, including internal processes, while e-commerce covers online buying and selling.", level: 1 },
      { q: "A consumer selling a used bicycle to another consumer through an online marketplace is an example of:", options: ["B2B", "B2C", "C2C", "Intra-B"], answer: 2, explain: "Consumer-to-consumer (C2C) business involves consumers dealing directly with each other.", level: 1 },
      { q: "Which of these is the first stage of an online transaction?", options: ["Purchase or sale", "Delivery", "Payment", "Pre-purchase or pre-sale"], answer: 3, explain: "The stages are pre-purchase/sale (information, advertising), purchase/sale (order, payment) and delivery.", level: 1 },
      { q: "Which of the following is a safeguard in e-business?", options: ["Encryption", "Cash on delivery", "Shopping cart", "Paperless records"], answer: 0, explain: "Encryption, passwords and OTPs, firewalls and secure payment gateways protect data and payments.", level: 1 },

      { q: "Case: Navkar Motors, a car maker, orders brake pads from its regular supplier through the supplier's online portal.\nThis is an example of:", options: ["C2C", "Intra-B", "B2C", "B2B"], answer: 3, explain: "Both parties are business firms, so it is business-to-business (B2B) e-business.", level: 2 },
      { q: "Case: Kisan Seeds Ltd has an internal network through which its marketing department sends customer orders directly to the production department.\nThis is called:", options: ["Intra-B e-business", "B2B e-business", "C2C e-business", "B2C e-business"], answer: 0, explain: "Interaction among departments and people within one firm is intra-business (Intra-B).", level: 2 },
      {
        q: "Assertion (A): E-business is a wider concept than e-commerce.\nReason (R): E-business also includes internal processes such as production, inventory management, human resources and finance carried out electronically.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 0, explain: "E-commerce is limited to buying, selling and customer–supplier interaction, whereas e-business adds internal processes. R explains A.", level: 2, keepOrder: true
      },
      { q: "Which of the following is a limitation of e-business?", options: ["Open 24 hours a day", "Global reach", "Orders taken in seconds but physical delivery takes days", "Movement towards a paperless society"], answer: 2, explain: "The gap between order-taking speed and delivery speed is a limitation. The others are benefits.", level: 2 },
      { q: "As compared to traditional business, e-business is generally:", options: ["Costlier and slower to set up", "Easier and cheaper to set up", "Dependent on a shop near the market", "Slower in responding to customers"], answer: 1, explain: "A website needs less money and fewer formalities than a physical shop, and no physical presence near the market is needed.", level: 2 },

      {
        q: "Assertion (A): In e-business, delivery of goods is completed instantly once the order is placed.\nReason (R): Orders in e-business can be placed in a matter of seconds.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 3, explain: "Orders are placed in seconds, but physical goods take days to reach the customer; only information products like software can be delivered instantly. So A is false and R is true.", level: 3, keepOrder: true
      },
      { q: "Case: A customer sees an online advertisement for a sofa, adds it to the shopping cart, pays by UPI and receives the sofa after four days.\nIn which stage does the payment take place?", options: ["Pre-purchase/sale stage", "Delivery stage", "Purchase/sale stage", "None of the stages"], answer: 2, explain: "Placing the order and making payment belong to the purchase/sale stage. The advertisement is pre-purchase; receiving the sofa is delivery.", level: 3 },
      { q: "Case: A hacker gets into the server of an online store and changes the delivery addresses stored there.\nThis is a risk of:", options: ["Default in payment", "Data storage and transmission", "Resistance to technology", "Low personal touch"], answer: 1, explain: "Data can be stolen or changed by hackers while it is stored or sent. This is a data storage and transmission risk.", level: 3 },
      { q: "A buyer places an order for a washing machine online but refuses to pay when it is delivered. Which risk of e-business is this?", options: ["Transaction risk (default in payment)", "Threat to intellectual property", "Data transmission risk", "Ethical fallout"], answer: 0, explain: "Default in placing an order, in delivery or in payment is a transaction risk.", level: 3 }
    ],
    written: [
      { q: "Define e-business.", a: "E-business means carrying out industry, trade and commerce using computer networks, mainly the internet.", marks: 1 },
      { q: "What is C2C e-business? Give an example.", a: "Consumer-to-consumer e-business is when consumers sell directly to other consumers, e.g. selling used books or furniture on an online marketplace.", marks: 1 },
      { q: "Distinguish between e-commerce and e-business on any two bases.", a: "(i) Scope: e-commerce is narrower and covers online buying and selling and interaction with customers and suppliers; e-business is wider and covers industry, trade and commerce.\n(ii) Processes: e-business also includes internal processes such as production, inventory, HR and finance done electronically; e-commerce does not.", marks: 2 },
      { q: "State any two limitations of e-business.", a: "(i) Low personal touch: face-to-face warmth is missing, which matters for items like textiles and jewellery.\n(ii) Need for technology capability among all parties, and increased risk due to anonymity of parties.", marks: 2 },
      { q: "Explain any three benefits of e-business.", a: "(i) Ease of formation and lower investment: a website costs less and needs fewer formalities than a physical shop.\n(ii) Convenience: open 24 hours a day, 7 days a week, 365 days a year.\n(iii) Global reach: sellers can reach buyers anywhere, and buyers can choose from sellers everywhere. (Speed and a paperless society are other benefits.)", marks: 3 },
      { q: "Explain B2B, B2C and Intra-B e-business with an example each.", a: "(i) B2B: transactions between firms, e.g. a car maker ordering components from suppliers online.\n(ii) B2C: firms selling to customers online, e.g. online shopping or banking.\n(iii) Intra-B: interaction among departments within one firm, e.g. marketing passing customer orders to production online.", marks: 3 },
      { q: "Compare e-business with traditional business on any three bases.", a: "(i) Ease of formation: e-business is easier and cheaper to set up; traditional business needs more money and formalities.\n(ii) Physical presence: e-business needs no physical presence near markets; traditional business usually needs a shop or office near customers.\n(iii) Response: e-business responds almost instantly; traditional business is slower.", marks: 3 },
      { q: "Explain the limitations of e-business.", a: "1. Low personal touch, which matters for products such as textiles and jewellery.\n2. Incongruence between order-taking and delivery speed: orders take seconds, goods take days.\n3. Need for technology capability among all parties.\n4. Increased risk due to the anonymity of parties.\n5. People's resistance to new technology.\n6. Ethical fallouts such as companies snooping on employees' emails and files.", marks: 5 },
      { q: "Explain the three stages of an online transaction and the modes of payment available.", a: "Stages:\n1. Pre-purchase/sale: information and advertising about products.\n2. Purchase/sale: the buyer registers on the site, adds items to the shopping cart, places the order and pays.\n3. Delivery of the goods or service.\nPayment modes: cash on delivery, cheque, net banking transfer, debit and credit cards, UPI and digital wallets.", marks: 5 },
      { q: "Case study: Malabar Masala Mart of Kochi sells spices to households through its own website. The site is open round the clock and customers pay by UPI or cash on delivery. Once, a hacker intercepted order details sent from the site, and some customers complained that parcels took a week to arrive.\n(i) Identify the type of e-business Malabar Masala Mart carries on.\n(ii) Name one benefit and one limitation of e-business that appear in the passage.\n(iii) Name the risk shown by the hacking incident and give one safeguard.", a: "(i) B2C (business-to-consumer).\n(ii) Benefit: convenience (24×7×365 availability). Limitation: incongruence between speed of order-taking and delivery.\n(iii) Data storage and transmission risk; safeguards include encryption, passwords and OTPs, firewalls or secure payment gateways (any one).", marks: 4, type: "case" }
    ]
  }
});
